    else:
        ws.cell(row=r, column=7).value = None

    if cur is None or nxt is None:
        for c in range(8, 11):
            ws.cell(row=r, column=c).value = None
        continue

    start = dt.datetime.combine(cur, start_time)
    end = dt.datetime.combine(nxt, end_time)

    for c in range(8, 11):
        prod = vws.cell(row=11, column=c).value
        if prod is None:
            ws.cell(row=r, column=c).value = None
            continue
        prod = str(prod).strip()

        total = 0.0
        for dtm, p, s in records:
            if p == prod and start <= dtm <= end:
                total += s

        if total == int(total):
            total = int(total)
        ws.cell(row=r, column=c).value = total

for r in range(12, 16):
    for c in range(8, 11):
        ws.cell(row=r, column=c).number_format = "$#,##0.00"

wb.save(OUT)

print("records:", len(records))
for r in range(12, 16):
    print(r, [ws.cell(row=r, column=c).value for c in range(7, 11)])
