import shutil
import openpyxl
from datetime import datetime, date, time, timedelta

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
sheet_name = wb.active.title
ws = wb[sheet_name]
vws = vals[sheet_name]

def parse_date_value(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, (int, float)):
        try:
            return (datetime(1899, 12, 30) + timedelta(days=float(v))).date()
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y", "%d-%m-%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except Exception:
                pass
    return None

def parse_time_value(v):
    if v is None:
        return None
    if isinstance(v, time):
        return v
    if isinstance(v, datetime):
        return v.time()
    if isinstance(v, (int, float)):
        try:
            frac = float(v) % 1.0
            total_seconds = int(round(frac * 86400))
            total_seconds %= 86400
            return time(total_seconds // 3600, (total_seconds % 3600) // 60, total_seconds % 60)
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%H:%M:%S", "%H:%M", "%I:%M:%S %p", "%I:%M %p"):
            try:
                return datetime.strptime(s, fmt).time()
            except Exception:
                pass
    return None

def to_number(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(',', '')
        try:
            return float(s)
        except Exception:
            return 0.0
    return 0.0

def norm_product(v):
    if v is None:
        return None
    s = str(v).strip()
    return s.upper() if s else None

records = []
for r in range(4, vws.max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value
    c = vws.cell(row=r, column=3).value
    d = vws.cell(row=r, column=4).value
    if a is None or c is None:
        continue
    d_date = parse_date_value(a)
    if d_date is None:
        continue
    t = parse_time_value(b)
    if t is None:
        if isinstance(a, datetime):
            dt = a
        else:
            dt = datetime.combine(d_date, time(0, 0, 0))
    else:
        dt = datetime.combine(d_date, t)
    prod = norm_product(c)
    if prod is None:
        continue
    records.append((dt, prod, to_number(d)))

